/* The vector files the on-chip test runs, in flash (generated by tests/device/bundle.py). */
#ifndef AB_BUNDLE_H
#define AB_BUNDLE_H

#include <stddef.h>

typedef struct {
    const char *name;
    int fmt;                    /* 0: key vectors, 1: format vectors (fmt_vectors), 2: a state image
                                   (unit 016: loaded and saved for the timing) */
    const char *text;
    size_t len;
} bundle_file;

extern const bundle_file BUNDLE[];
extern const unsigned BUNDLE_COUNT;

#endif
